/* Animación del logo en aerosol (WebGL). Archivo provisto por Teppan: no editar a mano. */
(function () {
  /* Teppan · logo escrito con aerosol. WebGL puro, sin dependencias.
     API: TeppanSpray.play() · TeppanSpray.render(ms) · TeppanSpray.duration · TeppanSpray.onComplete = fn
     Se ve una vez por carga de página; al volver al menú sin recargar aparece el logo final. */
  const LOGO = "data:image/png;base64,";
  const MAP  = "data:image/png;base64,";
  const DRIPS = [[286, 707, 70, 13, 321, 860], [826, 657, 110, 16, 1711, 980], [966, 659, 85, 13, 2215, 905]];      // x, y, largo, ancho, inicio ms, duración ms
  const END = 3620;
  const cv = document.getElementById("teppan-spray");
  const gl = cv.getContext("webgl", { premultipliedAlpha: true, preserveDrawingBuffer: true, antialias: true });
  const vs = `attribute vec2 p; varying vec2 uv; void main(){ uv = vec2(p.x*.5+.5, .5-p.y*.5); gl_Position = vec4(p,0.,1.); }`;
  const fs = `precision highp float;
  varying vec2 uv; uniform sampler2D uLogo, uMap; uniform float uT, uEnd;
  uniform vec4 uD[3]; uniform vec2 uDt[3];
  float h(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
  void main(){
    vec2 px = uv * 1080.0;
    vec4 m = texture2D(uMap, uv); vec4 lg = texture2D(uLogo, uv);
    float T = m.r*255.0*256.0 + m.g*255.0; float d = m.b*255.0;
    vec3 col = m.a > 0.75 ? vec3(0.949,0.529,0.020) : vec3(0.251,0.569,0.686);
    float n1 = h(floor(px)), n2 = h(floor(px/3.0)+7.0), n3 = h(floor(px/9.0)+3.0);
    float fadeMist = 1.0 - smoothstep(uEnd-650.0, uEnd-100.0, uT);
    vec4 outc = vec4(0.0);
    if (d < 0.5 && lg.a > 0.01) {
      // trazo: frente granulado de spray + «húmedo» que se seca
      float rv = smoothstep(-1.5, 1.5, uT - T);                          // trazo sólido, borde limpio
      vec3 c = lg.rgb / max(lg.a, 1e-3);
      outc = vec4(c, 1.0) * lg.a * rv;
    }
    // chorreaditos
    for (int i = 0; i < 3; i++) {
      vec4 D = uD[i]; vec2 Dt = uDt[i];
      float p = clamp((uT - Dt.x) / Dt.y, 0.0, 1.0);
      if (p <= 0.0) continue;
      float L = D.z * (1.0 - pow(1.0 - p, 2.6));
      float dy = px.y - D.y, dx = px.x - D.x;
      float fi = float(i);
      float w = D.w * 0.5 * (1.0 - 0.32 * clamp(dy / D.z, 0.0, 1.0)) * (0.94 + 0.06 * sin(dy * 0.045 + fi * 2.1));
      float body = (1.0 - smoothstep(w - 1.0, w + 1.0, abs(dx))) * step(0.0, dy) * (1.0 - smoothstep(L - 1.0, L + 1.0, dy));
      float top = 1.0 - smoothstep(0.9, 1.05, length(vec2(dx / (D.w * 0.75), (dy + 2.0) / 9.0)));       // une la gota con la letra
      float r = D.w * 0.52;
      float drop = 1.0 - smoothstep(0.92, 1.06, length(vec2(dx / r, (dy - L - r * 0.25) / (r * 1.3))));  // gota alargada
      float a = max(max(body, top), drop * smoothstep(0.0, 0.08, p));
      vec3 dc = vec3(0.949,0.529,0.020);
      outc = outc + vec4(dc, 1.0) * a * (1.0 - outc.a);
    }
    gl_FragColor = outc;
  }`;
  function sh(t, s){ const o = gl.createShader(t); gl.shaderSource(o, s); gl.compileShader(o);
    if (!gl.getShaderParameter(o, gl.COMPILE_STATUS)) throw gl.getShaderInfoLog(o); return o; }
  const pr = gl.createProgram(); gl.attachShader(pr, sh(gl.VERTEX_SHADER, vs)); gl.attachShader(pr, sh(gl.FRAGMENT_SHADER, fs)); gl.linkProgram(pr); gl.useProgram(pr);
  const b = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, b); gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1,1,-1,-1,1,1,1]), gl.STATIC_DRAW);
  const loc = gl.getAttribLocation(pr, "p"); gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
  function tex(img, unit, name){ const t = gl.createTexture(); gl.activeTexture(gl.TEXTURE0 + unit); gl.bindTexture(gl.TEXTURE_2D, t);
    gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.uniform1i(gl.getUniformLocation(pr, name), unit); }
  const uT = gl.getUniformLocation(pr, "uT"); gl.uniform1f(gl.getUniformLocation(pr, "uEnd"), END);
  gl.uniform4fv(gl.getUniformLocation(pr, "uD"), DRIPS.flatMap(d => [d[0], d[1], d[2], d[3]]));
  gl.uniform2fv(gl.getUniformLocation(pr, "uDt"), DRIPS.flatMap(d => [d[4], d[5]]));
  gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
  let ready = false, raf = 0;
  function render(ms){ if (!ready) return; gl.viewport(0, 0, cv.width, cv.height); gl.clearColor(0,0,0,0); gl.clear(gl.COLOR_BUFFER_BIT);
    gl.uniform1f(uT, ms); gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4); }
  function play(){ cancelAnimationFrame(raf); const t0 = performance.now();
    const loop = now => { const ms = now - t0; render(Math.min(ms, END)); if (ms < END) raf = requestAnimationFrame(loop); else if (API.onComplete) API.onComplete(); };
    raf = requestAnimationFrame(loop); }
  const API = window.TeppanSpray = { play, render, duration: END, onComplete: null, ready: null };
  // Se reproduce UNA vez por carga de página (entrar a la app o recargar).
  // Si se vuelve al menú sin recargar (navegación interna o botón «atrás»), muestra el logo ya pintado.
  function yaSeVio() {
    if (window.__teppanSprayVisto) return true;                       // mismo documento: volvió al menú dentro de la app
    const nav = performance.getEntriesByType && performance.getEntriesByType("navigation")[0];
    return !!(nav && nav.type === "back_forward");                     // volvió con «atrás» del navegador
  }
  function auto() {
    if (yaSeVio()) { render(END); if (API.onComplete) API.onComplete(); return; }
    window.__teppanSprayVisto = true; play();
  }
  window.addEventListener("pageshow", e => { if (e.persisted && ready) render(END); });   // página restaurada desde la caché del navegador
  let n = 0; const done = () => { if (++n === 2) { ready = true; render(0); if (!cv.dataset.manual) auto(); } };
  API.ready = new Promise(r => { const i1 = new Image(), i2 = new Image();
    i1.onload = () => { tex(i1, 0, "uLogo"); done(); if (n === 2) r(); }; i2.onload = () => { tex(i2, 1, "uMap"); done(); if (n === 2) r(); };
    i1.src = LOGO; i2.src = MAP; });
})();
